def make_shopping_words():
    words = []
    subs = ["shopping_clothing", "shopping_shoes", "shopping_stores", "shopping_money", "shopping_materials"]
    for i, w in enumerate(shopping_data):
        sub = subs[i // 50]
        words.append((w[0], w[1], w[2], f"[{w[0].lower()}]", w[3], w[4], w[5], w[6], "shopping", sub, w[7]))
    return words

SHOPPING_WORDS = make_shopping_words()
print("Shopping words generated:", len(SHOPPING_WORDS))
